/**
 * @file Build-time constants stamped by vite.config.ts `define`.
 */

/** The short git hash of the checkout that built this bundle. */
declare const __ARGUS_GIT__: string;

/** The UTC build timestamp, minute precision. */
declare const __ARGUS_BUILT__: string;

/** The bundled @fnndsc/menu wire-contract package version. */
declare const __ARGUS_MENU__: string;

/** True on the dev server, whose page is not the bundle a daemon serves. */
declare const __ARGUS_DEV__: boolean;
